SELECT CASE WHEN category IN ('Books', 'Sports') THEN 'priority' ELSE 'other' END AS category_group, CASE WHEN YEAR(launch_date) < 2024 THEN 'before_2024' WHEN YEAR(launch_date) = 2024 THEN '2024' ELSE 'after_2024' END AS launch_cohort, COUNT(cost) AS cost_count, COUNT(DISTINCT stock_qty) AS unique_categorys FROM products WHERE launch_date >= '2024-06-01' AND category = 'Sports' GROUP BY category_group, launch_cohort ORDER BY cost_count ASC;
